{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@spoons-and-mirrors/subtask2",
  "version": "0.3.5",
  "type": "module",
  "description": "Opencode plugin for enhanced subtask control with return context and prompt chaining",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "scripts": {
    "clean": "rm -rf dist",
    "build": "npm run clean && tsc",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "subtask",
    "chaining",
    "automation"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/spoons-and-mirrors/subtask2.git"
  },
  "author": "spoons-and-mirrors",
  "license": "PolyForm-Noncommercial-1.0.0",
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.216"
  },
  "dependencies": {
    "@opencode-ai/sdk": "latest",
    "yaml": "^2.8.2"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.217",
    "@types/node": "^25.0.3",
    "bun-types": "^1.3.5",
    "prettier": "^3.7.4",
    "typescript": "^5.9.3"
  },
  "files": [
    "dist/",
    "README.md",
    "LICENSE"
  ]
}
